formulas.expression:
IF( /* Si el campo de colección está vacío, inicializarlo */ ISBLANK({!$Record.Email_collection__c}),
/* Concatenar todos los correos actuales no vacíos al crear */ TRIM( IF(ISBLANK({!$Record.Email}), "", {!$Record.Email} & "; ") & IF(ISBLANK({!$Record.ASD_Email__c}), "", {!$Record.ASD_Email__c} & "; ") & IF(ISBLANK({!$Record.Previous_Email__c}), "", {!$Record.Previous_Email__c} & "; ") & IF(ISBLANK({!$Record.Company_Email__c}), "", {!$Record.Company_Email__c} & "; ") & IF(ISBLANK({!$Record.Portal_Email_Address__c}), "", {!$Record.Portal_Email_Address__c} & "; ") ),
/* Si ya tiene datos, agregar solo los campos que cambiaron y que no están vacíos ni duplicados */ {!$Record.Email_collection__c} & IF( AND( ISCHANGED({!$Record.Email}), NOT(ISBLANK({!$Record.Email})), NOT(CONTAINS({!$Record.Email_collection__c}, {!$Record.Email})) ), "; " & {!$Record.Email}, "" ) & IF( AND( ISCHANGED({!$Record.ASD_Email__c}), NOT(ISBLANK({!$Record.ASD_Email__c})), NOT(CONTAINS({!$Record.Email_collection__c}, {!$Record.ASD_Email__c})) ), "; " & {!$Record.ASD_Email__c}, "" ) & IF( AND( ISCHANGED({!$Record.Previous_Email__c}), NOT(ISBLANK({!$Record.Previous_Email__c})), NOT(CONTAINS({!$Record.Email_collection__c}, {!$Record.Previous_Email__c})) ), "; " & {!$Record.Previous_Email__c}, "" ) & IF( AND( ISCHANGED({!$Record.Company_Email__c}), NOT(ISBLANK({!$Record.Company_Email__c})), NOT(CONTAINS({!$Record.Email_collection__c}, {!$Record.Company_Email__c})) ), "; " & {!$Record.Company_Email__c}, "" ) & IF( AND( ISCHANGED({!$Record.Portal_Email_Address__c}), NOT(ISBLANK({!$Record.Portal_Email_Address__c})), NOT(CONTAINS({!$Record.Email_collection__c}, {!$Record.Portal_Email_Address__c})) ), "; " & {!$Record.Portal_Email_Address__c}, "" ) )
